/**
 * normalize-incoming.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * Takes the RAW payload from ANY of the 4 channels and emits ONE canonical record:
 *
 *   { user_id, channel, message, language, guest_name, received_at, raw }
 *
 * Every downstream node (memory, AI, Airtable, outbound) reads ONLY this shape.
 * user_id is ALWAYS channel-prefixed so a guest on two channels = one thread.
 *
 * n8n: input = $json (the webhook body). Output must be in `items`.
 * ------------------------------------------------------------------
 */

// ---- helpers --------------------------------------------------------
const UNKNOWN = 'unknown';

// Channel-local ISO-639-1 hint → maps messy locale strings to clean codes.
// (The AI does the real detection; this is just a fallback for the DB row.)
function localeToISO(s) {
  if (!s) return null;
  const x = String(s).toLowerCase().replace('_', '-');
  const map = {
    'fr': 'fr', 'fr-fr': 'fr', 'français': 'fr', 'francais': 'fr',
    'en': 'en', 'en-us': 'en', 'en-gb': 'en', 'english': 'en',
    'es': 'es', 'es-es': 'es', 'español': 'es',
    'de': 'de', 'de-de': 'de', 'deutsch': 'de',
    'it': 'it', 'pt': 'pt', 'pt-br': 'pt',
    'ru': 'ru', 'ja': 'ja', 'ko': 'ko', 'zh': 'zh', 'zh-cn': 'zh', 'zh-tw': 'zh',
    'ar': 'ar', 'nl': 'nl', 'pl': 'pl', 'tr': 'tr', 'hi': 'hi',
  };
  return map[x] || map[x.split('-')[0]] || null;
}

// WhatsApp / Meta envelopes are deeply nested. Walk down safely.
function path(obj, ...keys) {
  let cur = obj;
  for (const k of keys) {
    if (cur == null) return undefined;
    cur = cur[k];
  }
  return cur;
}

// Twilio posts x-www-form-urlencoded. In n8n, enable "Raw Data" on the webhook
// and the body lands as a string in $json.body. If it parses as querystring, do it.
function maybeParseForm(input) {
  if (typeof input !== 'string') return input;
  try {
    // n8n usually auto-parses form posts into the json object already.
    // If we still have a raw string, decode it.
    if (input.includes('=') && !input.trim().startsWith('{')) {
      const out = {};
      for (const pair of input.split('&')) {
        const [k, v] = pair.split('=');
        out[decodeURIComponent(k)] = decodeURIComponent((v || '').replace(/\+/g, ' '));
      }
      return out;
    }
  } catch (_) {}
  return input;
}

// ---- detection + normalization --------------------------------------
const rawBody = $json.body || $json || {};
const body = maybeParseForm(rawBody);

let channel = UNKNOWN;
let userIdRaw = '';
let message = '';
let language = null;
let guestName = '';

// 1) WhatsApp (Meta Cloud API)
if (path(body, 'object') === 'whatsapp_business_account' ||
    path(body, 'entry', 0, 'changes', 0, 'value', 'messaging_product') === 'whatsapp' ||
    path(body, 'entry', 0, 'changes', 0, 'value', 'messages')) {

  const value = path(body, 'entry', 0, 'changes', 0, 'value') || {};
  const msg = (value.messages || [])[0] || {};
  const contact = (value.contacts || [])[0] || {};

  if (msg.from || contact.wa_id) {
    channel = 'whatsapp';
    userIdRaw = msg.from || contact.wa_id;
    guestName = path(contact, 'profile', 'name') || '';
    // Only handle text for now; image/voice/interactive fall back to a placeholder.
    if (msg.type === 'text') {
      message = msg.text?.body || '';
    } else if (msg.type === 'interactive') {
      message = msg.interactive?.button_reply?.id ||
                msg.interactive?.list_reply?.id || '';
    } else {
      message = `[unsupported message type: ${msg.type}]`;
    }
  }
}

// 2) Instagram DM (Meta Graph API)
if (channel === UNKNOWN &&
    path(body, 'entry', 0, 'changes', 0, 'value', 'messaging_product') === 'instagram') {

  const value = path(body, 'entry', 0, 'changes', 0, 'value') || {};
  const msg = (value.messages || [])[0] || {};

  if (msg.sender?.id || msg.from) {
    channel = 'instagram';
    userIdRaw = msg.sender?.id || msg.from;
    guestName = msg.sender?.username || '';
    message = msg.message || msg.text || '';
  }
}

// 3) SMS via Twilio (form fields)
if (channel === UNKNOWN && (body.MessageSid || body.From)) {
  channel = 'sms';
  userIdRaw = (body.From || '').replace(/[^\d]/g, ''); // digits only
  message = body.Body || '';
  // Twilio gives no language hint.
}

// 4) Website widget (your script.js payload)
if (channel === UNKNOWN && (body.message || body.sessionId)) {
  channel = 'web';
  userIdRaw = body.sessionId || 'anon';
  message = body.message || '';
}

// Fallback: explicit channel field (custom integrations)
if (channel === UNKNOWN && body.channel) {
  channel = body.channel;
  userIdRaw = body.user_id || body.userId || body.sessionId || 'anon';
  message = body.message || body.text || '';
}

// ---- safety net -----------------------------------------------------
if (!message || !message.trim()) {
  // Empty/unsupported — still return a record so the workflow can politely
  // reply "I didn't catch that" instead of crashing.
  message = '[empty or unsupported message]';
}

// ---- build canonical record ----------------------------------------
const prefix = { whatsapp: 'wa', instagram: 'ig', sms: 'sms', web: 'web' }[channel] || 'x';
const user_id = `${prefix}:${userIdRaw}`;

const normalized = {
  user_id,
  channel,
  message,
  language,
  guest_name: guestName,
  received_at: new Date().toISOString(),
  raw: body, // keep for debugging; drop in prod if you want smaller logs
};

// n8n Code node contract: return array of items with `.json`
return [{ json: normalized }];

/**
 * build-airtable-query.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * Figures out WHAT to look up in Airtable from the guest's message, and emits
 * the `filterByFormula` string the Airtable node will use on the `Services` table.
 *
 * We use a lightweight keyword classifier (no AI needed here — fast + cheap).
 * The AI does the nuanced reasoning later; this just narrows the DB query so we
 * don't dump the whole catalog into the prompt.
 *
 * Input:  $json.message  (from normalize-incoming) + $json.language
 * Output: {
 *   category, tags[], filterByFormula, has_service_intent,
 *   likely_service_types[], scraped_search_query (used if Airtable misses)
 * }
 *
 * The Airtable node after this uses:
 *   Resource: Record   Operation: List   Table: Services
 *   FilterByFormula:   {{ $json.filterByFormula }}
 *   Sort:              PriceEUR DESC  (show premium options first)
 * ------------------------------------------------------------------
 */

const msg = (($json.message || '') + ' ' + ($json.guest_name || '')).toLowerCase();

// ---- 1. Category detection ----------------------------------------
// Multi-language keyword maps → canonical Category value (matches the
// Services table Single-Select exactly: spa|restaurant|tour|transport|experience).
const RULES = [
  {
    category: 'spa',
    keywords: ['spa', 'massage', 'masaje', 'massage', 'マッサージ', 'サ sauna', 'sauna',
               'hammam', 'wellness', 'treatment', 'soin', 'bain', 'facial', 'manucure'],
  },
  {
    category: 'restaurant',
    keywords: ['restaurant', 'dinner', 'lunch', 'breakfast', 'table', 'reservation',
               'resto', 'dîner', 'déjeuner', 'manger', 'food', 'eat', 'cuisine',
               'michelin', 'bistrot', 'brasserie', 'レストラン', '食事', 'comida'],
  },
  {
    category: 'transport',
    keywords: ['taxi', 'uber', 'chauffeur', 'car', 'driver', 'transfer', 'airport',
               'cdg', 'orly', 'pick up', 'pickup', 'cdg', 'navette', 'shuttle',
               'voiture', 'タクシー', '空港'],
  },
  {
    category: 'tour',
    keywords: ['tour', 'eiffel', 'louvre', 'museum', 'musée', 'cruise', 'croisière',
               'seine', 'versailles', 'excursion', 'sightsee', 'guide', 'montmartre',
               'd\'orsay', 'orsay', '観光', 'ツアー'],
  },
  {
    category: 'experience',
    keywords: ['private chef', 'chef', 'sommelier', 'wine tasting', 'dégustation',
               'after-hours', 'shopping', 'personal shopper', 'photographer',
               'proposal', 'anniversary', 'honeymoon', 'romantic'],
  },
];

// Tally hits per category to handle multi-intent ("spa + taxi to CDG").
const scores = {};
for (const r of RULES) {
  for (const kw of r.keywords) {
    if (msg.includes(kw)) scores[r.category] = (scores[r.category] || 0) + 1;
  }
}
const ranked = Object.entries(scores).sort((a, b) => b[1] - a[1]);
const primaryCategory = ranked.length ? ranked[0][0] : null;
const allCategories   = ranked.map(([c]) => c);

// ---- 2. Tags (refine within a category) ---------------------------
const tagSet = new Set();
const TAG_RULES = {
  couples:   ['couple', 'couples', 'deux', 'pour 2', '2 pax', '2 people', '二人', 'カップル'],
  vegan:     ['vegan', 'vegetarian', 'végétarien', 'végétarienne'],
  view:      ['view', 'eiffel view', 'rooftop', 'terrace', 'terrasse'],
  luxury:    ['vip', 'luxury', 'private', 'privé', 'premium', ' haut de gamme'],
  family:    ['family', 'kids', 'children', 'enfant', 'famille'],
  arrival:   ['arrival', 'check-in', 'cdg', 'orly', 'airport', 'landed'],
};
for (const [tag, kws] of Object.entries(TAG_RULES)) {
  for (const kw of kws) if (msg.includes(kw)) tagSet.add(tag);
}

// ---- 3. Build Airtable filterByFormula ---------------------------
// Active partners only; if we detected a category, restrict to it; else return
// all active partners (the AI will pick). AND({Active}, OR(...)) keeps it safe
// against injection (Airtable's formula language needs literal quotes).
let formula;
if (primaryCategory) {
  formula = `AND({Active}=TRUE(), {Category}="${primaryCategory}")`;
} else {
  formula = `{Active}=TRUE()`;
}
// Always restrict to active partners.

// ---- 4. Decide if this looks like a real service request ----------
// Heuristic: a category hit OR explicit request verbs.
const requestVerbs = ['book', 'reserve', 'need', 'want', 'arrange', 'organize',
                      'find', 'looking for', 'can you', 'i\'d like', 'je voudrais',
                      'réserver', 'je cherche', 'Reserve', '予約', '希望'];
const hasServiceIntent = !!primaryCategory ||
  requestVerbs.some(v => msg.includes(v));

// ---- 5. Search query for the external scraper (fallback) ----------
// Build a clean English query string in case Airtable misses.
// Use the primary category + original phrasing; strip filler.
function buildSearchQuery(category, original) {
  const parisTerm = 'Paris';
  const catLabel = {
    spa: 'spa', restaurant: 'restaurant', transport: 'private chauffeur taxi',
    tour: 'guided tour', experience: 'luxury experience',
  }[category] || '';
  // crude cleanup
  const cleaned = (original || '').replace(/\s+/g, ' ').trim().slice(0, 120);
  return `${catLabel} ${parisTerm} — ${cleaned}`.trim();
}

return [{
  json: {
    category:              primaryCategory,           // null if none
    categories_detected:   allCategories,
    tags:                  Array.from(tagSet),
    filterByFormula:       formula,
    has_service_intent:    hasServiceIntent,
    scraped_search_query:  buildSearchQuery(primaryCategory, $json.message),
    message:               $json.message,
    language:              $json.language,
    user_id:               $json.user_id,
    channel:               $json.channel,
  },
}];

/**
 * check-airtable-results.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * Decides whether the Airtable lookup found usable partners.
 * If YES → pass through (AI gets them).
 * If NO  → set `needs_scrape = true` so an IF node routes to the scraper.
 *
 * Input:  $json (query) + $json.airtable_services (rows from Airtable node)
 * Output: same query + { found_partners, needs_scrape, formatted_services_for_ai }
 *
 * Wiring:
 *   Airtable(List) → this Code node
 *   this Code node → IF node (condition: {{ $json.needs_scrape }})
 *      TRUE  → HTTP Request (scraper) → parse-scraper-results.js → merge
 *      FALSE → continue straight to build-ai-context.js
 * ------------------------------------------------------------------
 */

const query = $items('Build Service Query', 0, 0)[0]?.json || $json;
const rows = $input.all().map(item => item.json);

// Normalize Airtable rows (handle {fields:{}} wrapper)
function extract(row) {
  const f = row.fields || row.json?.fields || row.json || row || {};
  return {
    name:        f.Name || f.name || '',
    category:    f.Category || f.category || '',
    subType:     f.SubType || f.subType || '',
    description: f.Description || f.description || '',
    price:       f.PriceEUR ?? f['Price EUR'] ?? null,
    duration:    f.DurationMins ?? f['Duration (mins)'] ?? null,
    location:    f.Location || f.location || '',
    phone:       f.PhoneNumber || f['Phone Number'] || '',
    availability:f.Availability || f.availability || '',
    tags:        f.Tags || f.tags || [],
  };
}
const services = (Array.isArray(rows) ? rows : (rows.items || [])).map(extract)
  .filter(s => s.name); // drop empties

const foundPartners = services.length > 0;

// Pre-format for the prompt builder so it doesn't repeat this logic.
function fmtPrice(p) {
  if (p == null || p === '') return 'price on request';
  return `€${Number(p).toFixed(0)}`;
}
function fmtDur(d) {
  if (!d) return '';
  return ` · ${d} min`;
}

const formattedForAI = foundPartners
  ? services.map((s, i) => {
      const tags = Array.isArray(s.tags) && s.tags.length ? ` [${s.tags.join(', ')}]` : '';
      const phone = s.phone ? ` · phone ${s.phone}` : '';
      const avail = s.availability ? ` · avail: ${s.availability}` : '';
      return `${i + 1}. ${s.name} (${s.category}${s.subType ? ' / ' + s.subType : ''})` +
             ` — ${fmtPrice(s.price)}${fmtDur(s.duration)}${avail}${phone}${tags}\n` +
             `   ${s.description || ''}`.trimEnd() +
             (s.location ? `\n   @ ${s.location}` : '');
    }).join('\n\n')
  : '(no matching partner services found in the hotel catalog)';

return [{
  json: {
    ...query,
    found_partners:           foundPartners,
    needs_scrape:             !foundPartners && !!query.has_service_intent,
    services_count:           services.length,
    formatted_services_for_ai: formattedForAI,
    services_raw:             services,
  },
}];

/**
 * build-scraper-request.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * Builds the request body for the fallback web scraper.
 * Supports ScrapingBee OR Browserless (set $env.SCRAPER_PROVIDER).
 *
 * Strategy: we don't scrape the restaurant's own site (slow + brittle).
 * We scrape a Google search results page for the service + "Paris", then
 * parse-scraper-results.js extracts business name / phone / reviews from the
 * organic results. ScrapingBee/Browserless handle JS rendering + anti-bot.
 *
 * Output: { url, method, headers, body, provider } consumed by the HTTP Request node.
 *
 * Wire: check-airtable-results.js → IF(needs_scrape==true) → this node → HTTP Request
 * ------------------------------------------------------------------
 */

const provider   = ($env.SCRAPER_PROVIDER || 'scrapingbee').toLowerCase();
const search     = $json.scraped_search_query || ($json.category + ' Paris');
// Google search URL (encodeURIComponent keeps it safe).
const googleUrl  = 'https://www.google.com/search?q=' + encodeURIComponent(search + ' Paris');

// Cap how many external options we'll surface (parses top ~5 results).
const MAX_RESULTS = 5;

// Common instructions for the extraction step (passed via ScrapingBee's
// `extract_rules` or as a hint the parse node uses).
const extractHint = JSON.stringify({
  results: {
    selector: 'div.g, div.tF2Cxc',
    type: 'list',
    output: {
      title:   'h3',
      snippet: '.VwiC3b, .IsZvec',
      link:    'a @href',
    },
  },
});

let req;
if (provider === 'scrapingbee') {
  // ScrapingBee: GET with query params, returns rendered HTML.
  // Use the low-cost mode first; an escalation path can be added only for blocked searches.
  req = {
    provider,
    url:    'https://app.scrapingbee.com/api/v1/',
    method: 'GET',
    headers: { 'Content-Type': 'application/json' },
    // n8n HTTP "Send Query" fields:
    query: {
      api_key:           $env.SCRAPINGBEE_API_KEY,
      url:               googleUrl,
      render_js:         'false',
      premium_proxy:     'false',
      country_code:      'fr',
      // Custom header so Google thinks we're a Paris user → localized results.
      custom_google:     'true',
      block_ads:         'true',
      extract_rules:     extractHint,
    },
  };
} else if (provider === 'browserless') {
  // Browserless /function endpoint: run a tiny puppeteer script that returns
  // the first N organic results as JSON.
  const script = `
    module.exports = async ({ page }) => {
      await page.goto(${JSON.stringify(googleUrl)}, { waitUntil: 'networkidle2', timeout: 45000 });
      await page.waitForSelector('div.g, div.tF2Cxc', { timeout: 15000 }).catch(() => {});
      const items = await page.$$eval('div.g, div.tF2Cxc', els =>
        els.slice(0, ${MAX_RESULTS}).map(e => ({
          title:   e.querySelector('h3')?.innerText || '',
          snippet: e.querySelector('.VwiC3b, .IsZvec')?.innerText || '',
          link:    e.querySelector('a')?.href || '',
        })).filter(x => x.title)
      );
      return { results: items };
    };
  `;
  req = {
    provider,
    url:    `${$env.BROWSERLESS_URL || 'https://chrome.browserless.io'}/function?token=${$env.BROWSERLESS_TOKEN}`,
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: { code: script },
    useBody: true,
  };
} else {
  req = {
    provider: 'none',
    url: '',
    method: 'GET',
    warning: `Unknown SCRAPER_PROVIDER '${provider}'. Set $env.SCRAPER_PROVIDER to 'scrapingbee' or 'browserless'.`,
  };
}

return [{
  json: {
    ...$json,
    scraper_request:  req,
    scraper_max_results: MAX_RESULTS,
    google_search_url: googleUrl,
  },
}];

/**
 * parse-scraper-results.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * Normalizes the scraper's raw output into clean business records:
 *   { name, phone, rating, reviews_count, address, link, snippet, availability_guess }
 *
 * The scraper returns either ScrapingBee `extract_rules` JSON or Browserless
 * function JSON — both look like { results: [ {title, snippet, link} ] }.
 *
 * Phone numbers + ratings are usually IN the snippet. This node does cheap
 * regex extraction (no extra API calls) and de-dupes.
 *
 * Output: { found_external, external_options[], formatted_external_for_ai }
 * ------------------------------------------------------------------
 */

const MAX = 5;
const provider  = $json.provider || $json.scraper_request?.provider || 'unknown';

// Raw payload from the HTTP node. n8n puts the response body in $json.data or
// $json depending on "Response Format"; we handle both.
function unwrap(resp) {
  if (!resp) return { results: [] };
  // Browserless /function returns the function's return value at top level
  if (Array.isArray(resp.results)) return resp;
  // ScrapingBee extract_rules returns { results: {...} } or { body: '...' }
  if (resp.results) return resp;
  if (typeof resp.body === 'string') {
    // HTML fallback — pull <h3> + snippets with regex
    const html = resp.body;
    const titles = [...html.matchAll(/<h3[^>]*>([\s\S]*?)<\/h3>/g)]
      .map(m => m[1].replace(/<[^>]+>/g, '').trim()).filter(Boolean);
    return { results: titles.map(t => ({ title: t, snippet: '', link: '' })) };
  }
  return { results: [] };
}

const raw = unwrap($json.scraper_response || $json.data || $json);

// ---- extraction helpers --------------------------------------------
const PHONE_RE = /(?:\+?\d[\d\s().-]{7,}\d)/;
const RATING_RE = /(\d(?:[.,]\d)?)\s*(?:\/\s*5|\bstars?\b|\bstars\b|★★★★★?|\beval)/i;
const REVIEWS_RE = /(\d[\d.,]*)\s*(?:reviews?|avis|evaluations?|opinions?)/i;
const ADDR_RE = /\b(?:\d{1,3}\s+)?(?:rue|avenue|boulevard|bd|av\.?|place|pl\.?)\s+[^,\n]{3,60}/i;

function cleanTitle(t) {
  if (!t) return '';
  // Google often appends " - Restaurant à Paris" or "| Site officiel"
  return t.replace(/\s[–|\-|·]\s.*$/, '').replace(/\s{2,}/g, ' ').trim().slice(0, 120);
}

function firstMatch(re, s) {
  const m = (s || '').match(re);
  return m ? m[0].trim() : null;
}

// ---- build clean records -------------------------------------------
const seen = new Set();
const options = [];
for (const r of (raw.results || [])) {
  const title   = cleanTitle(r.title);
  if (!title || seen.has(title.toLowerCase())) continue;
  seen.add(title.toLowerCase());

  const text = `${title} ${r.snippet || ''}`;
  const phone  = firstMatch(PHONE_RE, text);
  const rating = firstMatch(RATING_RE, text);
  const nRev   = firstMatch(REVIEWS_RE, text);
  const addr   = firstMatch(ADDR_RE, text);

  options.push({
    name:             title,
    phone:            phone || null,
    rating:           rating || null,
    reviews_count:    nRev || null,
    address:          addr || 'Paris (exact address to be confirmed by staff)',
    link:             r.link || null,
    snippet:          (r.snippet || '').slice(0, 220),
    availability_guess: 'availability unknown — staff to confirm',
    source:           'external',
    provider,
  });
  if (options.length >= MAX) break;
}

const foundExternal = options.length > 0;

// Format for the AI prompt (clearly marked as NON-PARTNER).
const formattedForAI = foundExternal
  ? options.map((o, i) => {
      const bits = [
        `★ ${o.rating || 'n/a'}` + (o.reviews_count ? ` (${o.reviews_count})` : ''),
        o.phone ? `☎ ${o.phone}` : null,
        o.address ? `📍 ${o.address}` : null,
      ].filter(Boolean).join(' · ');
      return `${i + 1}. ${o.name} — NON-PARTNER\n   ${bits}\n   ${o.snippet}`.trimEnd();
    }).join('\n\n')
  : '(no external options found via web search)';

return [{
  json: {
    ...$json,
    found_external:              foundExternal,
    external_options:            options,
    external_options_count:      options.length,
    formatted_external_for_ai:   formattedForAI,
  },
}];

/**
 * fetch-and-shape-history.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * GIVES THE AI MEMORY.
 *
 * The Airtable node BEFORE this does a List operation on the `Conversations` table:
 *   filterByFormula = {UserID} = "<user_id>"
 *   sort            = Timestamp DESC
 *   limit           = 10
 *
 * That returns rows newest-first. This Code node:
 *   1. reverses them to oldest-first (chronological reading order),
 *   2. formats them into the compact chat-log string the OpenAI node expects,
 *   3. also returns the raw array in case a later node needs it.
 *
 * Input:  $json.user_id  +  $json.history_records (from the Airtable node output)
 * Output: { user_id, history_text, history_count, history_raw }
 *
 * Wiring: Airtable(List) → this Code node. Set the Airtable node's output to a
 * field named `history_records` via a Set node, or rename in the node's "Fields" UI.
 * Simplest: feed Airtable's items[] straight into this node as $items() and read
 * $json on each — here we assume the Airtable result was merged into $json.history_records.
 * ------------------------------------------------------------------
 */

function upstream(name) { try { return $items(name, 0, 0)[0]?.json || null; } catch (_) { return null; } }
const context = upstream('Parse Scraper Results') || upstream('Check Results (scrape?)') || {};
const userId = context.user_id || $json.user_id;
const records = $input.all().map(item => item.json);
const limit   = 10;

// Airtable returns newest-first (we sorted DESC). Reverse for readability.
// Defensive: each row may be { fields: {...} } (Airtable node format) or flat.
function extract(row) {
  const f = row.fields || row.json?.fields || row.json || row || {};
  return {
    role:      f.Role || f.role || 'user',
    message:   f.Message || f.message || '',
    language:  f.Language || f.language || '',
    timestamp: f.Timestamp || f['Created'] || f.timestamp || '',
  };
}

let msgs = (Array.isArray(records) ? records : (records.items || [])).map(extract);

// De-dupe identical consecutive messages (channels sometimes echo deliveries)
msgs = msgs.filter((m, i, arr) =>
  !(i > 0 && arr[i - 1].message === m.message && arr[i - 1].role === m.role)
);

// Oldest → newest
msgs.reverse();

// Cap to last N (Airtable already limited, but belt + suspenders)
if (msgs.length > limit) msgs = msgs.slice(-limit);

// Build the compact chat log the LLM reads.
// Format:  [hh:mm] user (fr): <text>
//          [hh:mm] assistant (fr): <text>
function fmtTime(iso) {
  if (!iso) return '--:--';
  try {
    return new Date(iso).toLocaleTimeString('en-GB', {
      hour: '2-digit', minute: '2-digit', hour12: false,
    });
  } catch { return '--:--'; }
}

const historyText = msgs.length === 0
  ? '(no prior conversation — this is the guest\'s first message)'
  : msgs.map(m => {
      const tag = m.language ? ` (${m.language})` : '';
      return `[${fmtTime(m.timestamp)}] ${m.role}${tag}: ${m.message}`.trim();
    }).join('\n');

return [{
  json: {
    ...context,
    user_id:       userId,
    history_text:  historyText,
    history_count: msgs.length,
    history_raw:   msgs,
  },
}];

function upstream(name) { try { return $items(name, 0, 0)[0]?.json || null; } catch (_) { return null; } }
const context = upstream('Shape History') || $json;
const settingRows = $input.all().map(item => item.json);
const settingsFactText = settingRows.map(row => {
  const fields = row.fields || row.json?.fields || row.json || row || {};
  return fields.Key ? `- ${fields.Key}: ${fields.Value ?? ''}` : '';
}).filter(Boolean).join('\n');
context.hotel_facts = settingsFactText || context.hotel_facts || '(hotel facts not loaded — answer generically)';

/**
 * build-ai-context.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * Assembles the single USER message the OpenAI node will send.
 * The system prompt (prompts/system-prompt.md) defines the placeholders;
 * this node fills them with real data so the LLM has everything in one block.
 *
 * Merges: inbound message + history + partner services + external options + hotel facts.
 *
 * Output: { ai_user_message, ai_temperature, ai_model_hint, ...passthrough }
 * The OpenAI node's "User Message" field = {{ context.ai_user_message }}
 * ------------------------------------------------------------------
 */

const hotelName = context.hotel_name || $env.HOTEL_NAME || 'Hôtel Lumière Paris';

// Hotel facts come from the Settings table (read earlier by an Airtable node
// and merged in as context.hotel_facts). If missing, fall back to a stub.
const hotelFacts = context.hotel_facts || '(hotel facts not loaded — answer generically)';

const services   = context.formatted_services_for_ai || '(no partner lookup performed)';
const external   = context.formatted_external_for_ai  || '(no external options)';
const history    = context.history_text               || '(no history)';
const guestMsg   = context.message                    || '';
const guestName  = context.guest_name                 ? ` (guest: ${context.guest_name})` : '';
const langHint   = context.language                   ? ` | channel locale hint: ${context.language}` : '';

// Assemble the prompt. Clear section headers help the LLM attend correctly.
const userMessage = `
=== GUEST MESSAGE ===
${guestMsg}

=== CHANNEL ===
${context.channel}${guestName}${langHint}

=== CONVERSATION HISTORY (last ${context.history_count ?? 0} messages, oldest→newest) ===
${history}

=== PARTNER SERVICES AVAILABLE (hotel catalog — PREFERRED) ===
${services}

=== EXTERNAL OPTIONS (NON-PARTNER — found via web search; present as suggestions only) ===
${external}

=== HOTEL FACTS ===
${hotelFacts}

=== INSTRUCTIONS ===
Follow the OUTPUT CONTRACT from your system prompt exactly. Reply in the guest's language.
Use partner services first. If none fit, present external options clearly marked as non-partner.
At most ONE upsell, only if natural. Output JSON only.
`.trim();

return [{
  json: {
    ...context,
    ai_user_message: userMessage,
    ai_temperature:  0.4,        // low temp = consistent JSON + tone
    ai_model_hint:   'gpt-4o-mini',
    hotel_name:      hotelName,
  },
}];

/**
 * parse-ai-output.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * Hardens the OpenAI node's response into a guaranteed-shape object.
 * LLMs occasionally wrap JSON in ``` fences, add prose, or truncate. This node
 * extracts the JSON robustly, validates the contract, and NEVER throws — on
 * failure it falls back to a safe message so the guest still gets a reply.
 *
 * Input:  $json.message.content (OpenAI node output) OR $json.ai_raw
 * Output: {
 *   reply_text, language_detected, intent, service_type, requests[],
 *   upsell_offered, requires_human, requires_scrape, parse_ok, parse_error
 * }
 *
 * After this node:
 *   - branch A → log conversation to Airtable (Conversations)
 *   - branch B → IF(requests.length>0) → create Request rows in Airtable
 *   - branch C → format-outbound.js → send to channel
 * ------------------------------------------------------------------
 */

const raw = ($json.message?.content) || $json.ai_raw || $json.text || '';

// --- 1. Extract the JSON object from the model's text ----------------
function extractJSON(text) {
  if (!text) return null;
  const t = String(text).trim();

  // Fast path: already pure JSON
  if (t.startsWith('{') && t.endsWith('}')) {
    try { return JSON.parse(t); } catch {}
  }
  // Strip markdown fences ```json ... ```
  const fenced = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) {
    try { return JSON.parse(fenced[1].trim()); } catch {}
  }
  // Find the first {...} block
  const start = t.indexOf('{');
  const end   = t.lastIndexOf('}');
  if (start !== -1 && end > start) {
    const slice = t.slice(start, end + 1);
    try { return JSON.parse(slice); } catch (e) { /* fall through */ }
  }
  return null;
}

const parsed = extractJSON(raw);

// --- 2. Validate + coerce fields -------------------------------------
function str(x, def = '')      { return typeof x === 'string' ? x : (x == null ? def : String(x)); }
function arr(x)                { return Array.isArray(x) ? x : []; }
function bool(x, def = false)  { return typeof x === 'boolean' ? x : def; }
function numOrNull(x) {
  if (x == null || x === '') return null;
  const n = Number(String(x).replace(/[^\d.,-]/g, '').replace(',', '.'));
  return isFinite(n) ? n : null;
}

const ALLOWED_INTENTS = ['faq','service_request','upsell_accept','upsell_decline',
                         'smalltalk','complaint','other'];

let result;
let parseOk = true;
let parseError = null;

if (parsed) {
  const intent = ALLOWED_INTENTS.includes(parsed.intent) ? parsed.intent : 'other';
  result = {
    reply_text:        str(parsed.reply_text || parsed.reply || parsed.message),
    language_detected: str(parsed.language_detected || parsed.language, 'unknown').slice(0, 5).toLowerCase(),
    language_confidence: str(parsed.language_confidence, 'medium'),
    intent,
    service_type:      parsed.service_type || null,
    requests:          arr(parsed.requests).map(r => ({
      service_name:    r.service_name || null,
      source:          r.source === 'external' ? 'external' : 'partner',
      service_type:    r.service_type || parsed.service_type || 'other',
      summary:         str(r.summary),
      est_value_eur:   numOrNull(r.est_value_eur),
      is_upsell:       bool(r.is_upsell),
      guest_confirmed: bool(r.guest_confirmed),
    })),
    upsell_offered:    parsed.upsell_offered || null,
    requires_human:    bool(parsed.requires_human),
    requires_scrape:   bool(parsed.requires_scrape),
  };
} else {
  // Fallback: model didn't return clean JSON. Use raw text as the reply.
  parseOk = false;
  parseError = 'AI output was not valid JSON; using raw text as reply.';
  result = {
    reply_text: str(raw) || 'My apologies — I had trouble processing that. Could you rephrase?',
    language_detected: 'unknown',
    language_confidence: 'low',
    intent: 'other',
    service_type: null,
    requests: [],
    upsell_offered: null,
    requires_human: false,
    requires_scrape: false,
  };
}

// --- 3. Carry through context needed by downstream nodes --------------
return [{
  json: {
    ...$json,                       // keep user_id, channel, message, history, etc.
    ...result,                      // parsed fields (override any collisions)
    ai_raw:           raw,
    parse_ok:         parseOk,
    parse_error:      parseError,
    has_requests:     result.requests.length > 0,
    total_est_value:  result.requests.reduce((s, r) => s + (r.est_value_eur || 0), 0),
  },
}];

const source = $json;
return (source.requests || []).map(request => ({
  json: {
    user_id: source.user_id,
    channel: source.channel,
    guest_name: source.guest_name || '',
    language_detected: source.language_detected || 'unknown',
    request,
  },
}));

/**
 * format-outbound.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * REVERSE of normalize-incoming.js.
 * Input: the parsed AI output + the original normalized inbound record.
 *   $json.ai_text         → the final text to send the guest
 *   $json.channel         → where it came from
 *   $json.user_id         → channel-prefixed id
 *   $json.raw             → original inbound payload (so we can extract IDs)
 *
 * Output (single item) carries ready-to-send payloads AND a `web_reply` field.
 * Wire this node into 4 conditional branches with an n8n IF/Switch on `channel`:
 *
 *   branch whatsapp   → HTTP Request (Meta send)
 *   branch instagram  → HTTP Request (IG send)
 *   branch sms        → HTTP Request (Twilio REST)  OR return TwiML to webhook
 *   branch web        → Respond to Webhook with { reply: <text> }
 *
 * Each branch only fires for its channel; the others are no-ops. That keeps
 * the payload-shaping logic in ONE place (here) instead of scattered across nodes.
 * ------------------------------------------------------------------
 */

const aiText    = $json.reply_text || $json.ai_text || $json.text || '';
const channel   = $json.channel || 'unknown';
const userId    = $json.user_id || '';
const lang      = $json.language_detected || $json.language || null;

// Split the user_id back into the channel-local id
const [, localId] = userId.split(':'); // "wa:33612..." → ["wa","33612..."]

// WhatsApp: pull the original `from`/message id from the raw inbound so we reply in-thread.
function buildWhatsApp(aiText, raw) {
  const msg    = raw?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
  const waFrom = msg?.from || localId;
  return {
    url: `${$env.WA_BASE_URL || 'https://graph.facebook.com/v19.0'}/${$env.WA_PHONE_NUMBER_ID}/messages`,
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${$env.WA_TOKEN}`,
      'Content-Type':  'application/json',
    },
    body: {
      messaging_product: 'whatsapp',
      to: waFrom,
      type: 'text',
      text: { body: aiText }, // WhatsApp caps text.body at 4096 chars
    },
    sendMetadata: { type: 'whatsapp_text', to: waFrom },
  };
}

// Instagram: recipient id = IG-scoped sender id.
function buildInstagram(aiText, raw) {
  const msg    = raw?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
  const igFrom = msg?.sender?.id || localId;
  return {
    url: `${$env.IG_BASE_URL || 'https://graph.facebook.com/v19.0'}/${$env.IG_BUSINESS_ACCOUNT_ID}/messages`,
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${$env.IG_TOKEN}`,
      'Content-Type':  'application/json',
    },
    body: {
      recipient: { id: igFrom },
      message:   { text: aiText },
    },
    sendMetadata: { type: 'instagram_text', to: igFrom },
  };
}

// SMS via Twilio REST. (If you prefer the inbound-reply pattern, use web_reply
// below with Content-Type text/xml instead — same node, different branch.)
function buildSMS(aiText, raw) {
  const from = (raw?.From || `+${localId}`).replace(/[^\d+]/g, '');
  return {
    url: `${$env.TWILIO_BASE_URL || 'https://api.twilio.com'}/2010-04-01/Accounts/${$env.TWILIO_ACCOUNT_SID}/Messages.json`,
    method: 'POST',
    headers: {
      'Authorization': 'Basic ' + Buffer
        .from(`${$env.TWILIO_ACCOUNT_SID}:${$env.TWILIO_AUTH_TOKEN}`)
        .toString('base64'),
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    // n8n HTTP Request node wants form fields as body when sending as form.
    body: {
      To: from,
      From: $env.TWILIO_FROM_NUMBER,
      Body: aiText,
    },
    sendMetadata: { type: 'sms_text', to: from },
  };
}

// Web: no API call needed — the Webhook node returns this JSON to the widget.
// The widget's script.js already reads `data.reply`.
function buildWeb(aiText) {
  return {
    web_reply: { reply: aiText, language: lang },
  };
}

// ---- dispatch -------------------------------------------------------
const raw = $json.raw || {};
let outbound = {};

switch (channel) {
  case 'whatsapp':  outbound = buildWhatsApp(aiText, raw);  break;
  case 'instagram': outbound = buildInstagram(aiText, raw); break;
  case 'sms':       outbound = buildSMS(aiText, raw);       break;
  case 'web':       outbound = buildWeb(aiText);            break;
  default:
    // Unknown channel — best effort: expose a generic web_reply + log.
    outbound = buildWeb(aiText);
    outbound.warning = `Unknown channel '${channel}' — defaulted to web_reply.`;
}

return [{
  json: {
    channel,
    user_id: userId,
    ai_text: aiText,
    language_detected: lang,
    // The Switch/IF node after this reads `channel` and routes to the right HTTP node.
    // Each HTTP node reads the matching fields below.
    whatsapp_payload:  outbound.body && channel === 'whatsapp'  ? outbound : null,
    instagram_payload: outbound.body && channel === 'instagram' ? outbound : null,
    sms_payload:       outbound.body && channel === 'sms'       ? outbound : null,
    web_reply:         outbound.web_reply || null,
    outbound_meta: outbound.sendMetadata || null,
    warning: outbound.warning || null,
  },
}];

/**
 * build-morning-summary.js  —  n8n Code node (JavaScript, "Run Once for All Items")
 * ------------------------------------------------------------------
 * THE MORNING HANDOFF (Staff Execution).
 *
 * This node runs in a SEPARATE scheduled workflow triggered at 08:00 Paris time
 * (n8n Schedule Trigger → set timezone Europe/Paris → cron 0 8 * * *).
 *
 * It consumes the rows the Schedule→Airtable(List) branch pulled from the
 * `Requests` table (all rows where Status=new AND HandoverAt is empty AND
 * CreatedAt >= yesterday 22:00). It produces:
 *
 *   1. `email_html`    → professional HTML email body for the Send Email node
 *   2. `whatsapp_text` → tight WhatsApp message for the WhatsApp Business send node
 *   3. `row_ids[]`     → ids to mark HandoverAt=now after sending (prevent re-send)
 *
 * Input:  $json.requests[] (array of Request rows from the Airtable List node)
 * Output: { email_html, email_subject, whatsapp_text, total_value_eur,
 *           upsell_count, request_count, row_ids }
 * ------------------------------------------------------------------
 */

const hotelName = $env.HOTEL_NAME || 'Hôtel Lumière Paris';
const rows = $input.all().map(item => item.json);

// Normalize rows (Airtable wraps in {fields:{...}})
function extract(row) {
  const f = row.fields || row.json?.fields || row.json || row || {};
  return {
    id:          row.id || f.RequestID || f.id || null,
    user_id:     f.UserID || '',
    guest:       f.GuestName || '(unknown guest)',
    channel:     f.Channel || '?',
    serviceType: f.ServiceType || 'other',
    summary:     f.RequestSummary || '',
    source:      f.Source || 'partner',
    serviceRef:  f.ServiceRef || '',
    status:      f.Status || 'new',
