    language:    f.Language || '',
    createdAt:   f.CreatedAt || f['Created'] || '',
  };
}
const items = (Array.isArray(rows) ? rows : (rows.items || [])).map(extract);

// Totals for the headline numbers (your free-trial ROI proof!)
const totalValue = items.reduce((s, r) => s + (r.estValue || 0), 0);
const upsellCount = items.filter(r => r.isUpsell).length;

// Channel emoji map
const CH = { whatsapp: 'WhatsApp', instagram: 'Instagram', sms: 'SMS', web: 'Website' };

// --- 1. WhatsApp summary (keep it short — manager is on mobile) -----
function fmtShortTime(iso) {
  try {
    return new Date(iso).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
  } catch { return '--:--'; }
}

let wa = `☀️ *Bonjour ${hotelName} — Morning Handoff*\n\n`;
wa += `${items.length} new overnight request(s)`;
if (upsellCount) wa += ` · ${upsellCount} AI upsell(s)`;
wa += ` · *€${totalValue.toFixed(0)} potential revenue*\n\n`;

if (items.length === 0) {
  wa += '✅ Nothing pending. Have a beautiful day.';
} else {
  items.slice(0, 12).forEach((r, i) => {
    const tag = r.isUpsell ? ' 🎁 upsell' : '';
    const src = r.source === 'external' ? ' [external]' : '';
    wa += `${i + 1}. *${r.serviceType.toUpperCase()}* — ${r.guest}${tag}${src}\n`;
    wa += `   ${r.summary}\n`;
    if (r.estValue)  wa += `   €${r.estValue} · `;
    else             wa += `   `;
    wa += `${CH[r.channel] || r.channel} · ${fmtShortTime(r.createdAt)}\n\n`;
  });
  if (items.length > 12) wa += `…+${items.length - 12} more in the full email.\n`;
  wa += `Full details: check your inbox.`;
}

// --- 2. HTML email (clean, scannable, on-brand) ---------------------
const ROWS_HTML = items.length === 0
  ? `<tr><td colspan="6" style="padding:32px;text-align:center;color:#888;">` +
    `Nothing pending overnight. Quiet night — enjoy your coffee. ☕</td></tr>`
  : items.map((r, i) => {
      const val = r.estValue ? `€${r.estValue.toFixed(0)}` : '<span style="color:#bbb">—</span>';
      const upsell = r.isUpsell
        ? `<span style="background:#C5A059;color:#fff;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600;">UPSELL</span>`
        : '';
      const src = r.source === 'external'
        ? `<span style="color:#b8860b;font-size:11px;">⚠ external</span>` : '';
      return `
      <tr style="border-bottom:1px solid #eee;">
        <td style="padding:12px 8px;font-weight:600;color:#0A192F;">${i + 1}</td>
        <td style="padding:12px 8px;">
          <div style="font-weight:600;color:#0A192F;">${escapeHtml(r.summary)}</div>
          <div style="font-size:12px;color:#888;margin-top:2px;">
            ${escapeHtml(r.guest)} · ${CH[r.channel] || r.channel} · ${fmtShortTime(r.createdAt)}
            ${r.serviceRef ? ` · <em>${escapeHtml(r.serviceRef)}</em>` : ''}
          </div>
        </td>
        <td style="padding:12px 8px;text-transform:uppercase;font-size:11px;color:#C5A059;font-weight:600;letter-spacing:0.5px;">${r.serviceType}</td>
        <td style="padding:12px 8px;text-align:right;font-weight:600;color:#0A192F;">${val}</td>
        <td style="padding:12px 8px;text-align:center;">${upsell}</td>
        <td style="padding:12px 8px;text-align:center;">${src}</td>
      </tr>`;
    }).join('');

const emailHtml = `<!DOCTYPE html>
<html><body style="margin:0;padding:0;background:#F5F5F5;font-family:'Inter','Helvetica Neue',Arial,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#F5F5F5;padding:24px;">
    <tr><td align="center">
