          </div>
          <div style="color:rgba(255,255,255,0.7);font-size:13px;margin-top:6px;">
            Overnight handoff · ${new Date().toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long' })}
          </div>
        </td></tr>

        <!-- KPIs -->
        <tr><td style="padding:24px 40px 0;">
          <table width="100%" cellpadding="0" cellspacing="0">
            <tr>
              <td style="width:33%;text-align:center;padding:16px;background:#FAF8F2;border-radius:8px;">
                <div style="font-family:Georgia,serif;font-size:28px;color:#C5A059;font-weight:700;">${items.length}</div>
                <div style="font-size:11px;color:#888;text-transform:uppercase;letter-spacing:1px;">Requests</div>
              </td>
              <td style="width:33%;text-align:center;padding:16px;background:#FAF8F2;border-radius:8px;">
                <div style="font-family:Georgia,serif;font-size:28px;color:#C5A059;font-weight:700;">€${totalValue.toFixed(0)}</div>
