      </table>
    </td></tr>
  </table>
</body></html>`;

function escapeHtml(s) {
  return String(s || '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

return [{
  json: {
    email_subject:   `☀️ ${hotelName} — ${items.length} overnight requests · €${totalValue.toFixed(0)} potential`,
    email_html:      emailHtml,
    whatsapp_text:   wa,
